  const [now] = useState(() => Date.now());

  if (!scene) {
    return (
      <section className="pb-tabbar flex min-h-dvh flex-col items-center justify-center gap-4 p-6">
        <p className="text-muted">nothing seen yet</p>
        <button
          type="button"
          onClick={() => go("look")}
          className="rounded-[26px] bg-accent px-6 py-3 text-[length:var(--text-m)] font-semibold text-card"
        >
          look
        </button>
      </section>
    );
  }

  const placed = scene.objects.filter((o) => o.bbox);
  const stacked = scene.objects.filter((o) => !o.bbox);

  function keep(obj: SceneObject) {
    store.keep({
      phrase_fr: obj.phrase_fr,
      phrase_en: obj.phrase_en,
      noun_fr: obj.fr,
      objectId: obj.id,
      place: scene!.place,
      crop: session.frame ?? undefined,
    });
    setVersion((v) => v + 1);
  }

  return (
    <section className="bg-night pb-tabbar flex min-h-dvh flex-col text-snow">
      <div className="relative min-h-[120px]">
        {session.frame && <img src={session.frame} alt={scene.place} className="block w-full" />}
        <div aria-hidden className="pointer-events-none absolute inset-x-0 top-0 h-[120px] bg-gradient-to-b from-[var(--camera-dim)] to-transparent" />
        <div aria-hidden className="pointer-events-none absolute inset-x-0 bottom-0 h-[160px] bg-gradient-to-t from-[var(--camera-dim)] to-transparent" />
        <header className="pt-safe absolute inset-x-0 top-0 z-10 flex items-center gap-3 px-4">
          <GlassButton variant="dark" aria-label="look again" onClick={() => go("look")}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
              <path d="M15 5l-7 7 7 7" />
            </svg>
          </GlassButton>
          <p className="glass-dark glass-specular flex h-9 min-w-0 items-center rounded-[18px] px-4 text-[15px] font-semibold">
            <span className="truncate">{scene.task.fr}</span>
          </p>
        </header>
        {placed.map((obj) => {
          const [x, y, w, h] = obj.bbox!;
          return (
            <div
              key={obj.id}
              className="absolute flex -translate-x-1/2 -translate-y-1/2 flex-col items-center gap-1"
              style={{ left: `${(x + w / 2) * 100}%`, top: `${(y + h / 2) * 100}%` }}
            >
              <Pill obj={obj} now={now} active={open?.id === obj.id} onOpen={() => setOpen(obj)} />
              <span aria-hidden className="h-2 w-2 rounded-[var(--radius-pill)] bg-snow" />
            </div>
          );
        })}
      </div>

      <p className="px-4 pt-4 text-[length:var(--text-s)] text-snow/72">{scene.task.en}</p>

      {stacked.length > 0 && (
        <div className="flex flex-wrap gap-2 p-4">
          {stacked.map((obj) => (
            <Pill key={obj.id} obj={obj} now={now} active={open?.id === obj.id} onOpen={() => setOpen(obj)} />
          ))}
        </div>
      )}

      {open && (
        <div
          role="dialog"
          aria-label={open.fr}
          className="fixed inset-x-0 bottom-0 z-50 mx-auto max-w-md rounded-t-[var(--radius-sheet)] bg-paper/96 px-6 pt-2 pb-[calc(24px+env(safe-area-inset-bottom))] text-ink shadow-lg backdrop-blur-[20px]"
        >
          <span aria-hidden className="mx-auto mb-3 block h-[5px] w-9 rounded-[var(--radius-pill)] bg-[#C9C7C1]" />
          <div className="flex items-start justify-between">
            <p className="font-display text-[length:var(--text-xl)] leading-[var(--lh-h2)] font-bold">
              {open.fr.startsWith(open.article) ? open.fr : `${open.article} ${open.fr}`}
            </p>
            <GlassButton aria-label="close" onClick={() => setOpen(null)}>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" aria-hidden>
                <path d="M6 6l12 12M18 6L6 18" />
              </svg>
            </GlassButton>
          </div>
          <p className="text-[length:var(--text-s)] text-muted">
            {open.gender === "m" ? "masculine" : "feminine"} · plural {open.plural}
          </p>
          <p className="mt-4 text-[length:var(--text-l)]">{open.phrase_fr}</p>
          <p className="text-[length:var(--text-s)] text-muted">{open.phrase_en}</p>
          <div className="mt-6 flex gap-3">
            <button
              type="button"
              onClick={() => keep(open)}
              className="h-[52px] flex-1 rounded-[26px] border border-line bg-card px-4 text-[length:var(--text-m)] font-semibold"
            >
              keep
            </button>
            <button
              type="button"
              onClick={() => {
                session.recallCardId = findRecall(scene, store.all())?.id ?? null;
                go("roleplay");
              }}
              className="h-[52px] flex-1 rounded-[26px] bg-accent px-4 text-[length:var(--text-m)] font-semibold text-card"
            >
              talk
            </button>
          </div>
        </div>
      )}
    </section>
  );
}
export async function startCamera(video: HTMLVideoElement): Promise<MediaStream> {
  if (!navigator.mediaDevices?.getUserMedia) throw new Error("camera unavailable");
  const stream = await navigator.mediaDevices.getUserMedia({
    video: { facingMode: "environment" },
    audio: false,
  });
  video.srcObject = stream;
  await video.play().catch(() => undefined);
  return stream;
}

export function stopCamera(stream: MediaStream | null | undefined): void {
  stream?.getTracks().forEach((t) => t.stop());
}

export function captureJpeg(source: HTMLVideoElement | HTMLImageElement, maxEdge = 1024): string {
  const w = source instanceof HTMLVideoElement ? source.videoWidth : source.naturalWidth;
  const h = source instanceof HTMLVideoElement ? source.videoHeight : source.naturalHeight;
  if (!w || !h) throw new Error("no frame");
  const scale = Math.min(1, maxEdge / Math.max(w, h));
  const canvas = document.createElement("canvas");
  canvas.width = Math.round(w * scale);
  canvas.height = Math.round(h * scale);
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("no canvas");
  ctx.drawImage(source, 0, 0, canvas.width, canvas.height);
  return canvas.toDataURL("image/jpeg", 0.85);
}

export function fileToJpeg(file: File, maxEdge = 1024): Promise<string> {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      try {
        resolve(captureJpeg(img, maxEdge));
      } catch (e) {
        reject(e);
      } finally {
        URL.revokeObjectURL(url);
      }
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("could not read image"));
    };
    img.src = url;
  });
}
import { act, fireEvent, render, screen, waitFor, within } from "@testing-library/react";
import { go, useScreen } from "../lib/screen";
import { session, resetSession } from "../lib/session";
import type { SceneResult } from "../lib/types";
import * as store from "../srs/store";
import Look from "./Look";
import Scene from "./Scene";

vi.mock("../lib/api", () => ({
  postScene: vi.fn(),
}));

const fixture: SceneResult = {
  place: "café",
  task: { fr: "commande un café", en: "order a coffee", role: "serveur" },
  objects: [
    {
      id: "o1",
      fr: "la machine à café",
      en: "the coffee machine",
      article: "la",
      gender: "f",
      plural: "les machines à café",
      level: "A1",
      phrase_fr: "la machine à café est chaude",
      phrase_en: "the coffee machine is hot",
      bbox: [0.1, 0.1, 0.2, 0.2],
    },
    {
      id: "o2",
      fr: "la tasse",
      en: "the cup",
      article: "la",
      gender: "f",
      plural: "les tasses",
      level: "A1",
      phrase_fr: "une tasse, s'il vous plaît",
      phrase_en: "a cup, please",
      bbox: [0.5, 0.5, 0.1, 0.1],
    },
    {
      id: "o3",
      fr: "le sucre",
      en: "the sugar",
      article: "le",
      gender: "m",
      plural: "les sucres",
      level: "A1",
      phrase_fr: "avec du sucre",
      phrase_en: "with sugar",
    },
  ],
};

function ScreenProbe() {
  return <output data-testid="screen">{useScreen().screen}</output>;
}

describe("Look", () => {
  it("renders the file fallback when getUserMedia rejects", async () => {
    Object.defineProperty(navigator, "mediaDevices", {
      configurable: true,
      value: { getUserMedia: vi.fn().mockRejectedValue(new Error("denied")) },
    });
    const { container } = render(<Look />);
    await waitFor(() => {
      expect(container.querySelector('input[type="file"]')).not.toBeNull();
    });
    const input = container.querySelector('input[type="file"]')!;
    expect(input.getAttribute("accept")).toBe("image/*");
    expect(input.getAttribute("capture")).toBe("environment");
    expect(screen.getByText("point at anything")).toBeInTheDocument();
  });
});

describe("Scene", () => {
  beforeEach(() => {
    localStorage.clear();
    store.clear();
    resetSession();
    act(() => go("scene"));
    session.scene = fixture;
    session.frame = "data:image/jpeg;base64,AAAA";
  });

  it("renders pills, opens the sheet, keeps a card and talks", () => {
    render(
      <>
        <ScreenProbe />
        <Scene />
      </>,
    );
    for (const o of fixture.objects) {
      expect(screen.getByRole("button", { name: o.fr })).toBeInTheDocument();
    }

    fireEvent.click(screen.getByRole("button", { name: "la machine à café" }));
    const sheet = screen.getByRole("dialog");
    expect(within(sheet).getByText("la machine à café")).toBeInTheDocument();
    expect(within(sheet).getByText("la machine à café est chaude")).toBeInTheDocument();

    fireEvent.click(within(sheet).getByRole("button", { name: "keep" }));
    expect(store.all()).toHaveLength(1);
    expect(store.all()[0].noun_fr).toBe("la machine à café");
    expect(screen.getByRole("button", { name: "la machine à café" })).toHaveAttribute("data-state", "known");

    fireEvent.click(within(sheet).getByRole("button", { name: "talk" }));
    expect(screen.getByTestId("screen")).toHaveTextContent("roleplay");
  });

  it("shows an empty state without a scene", () => {
    session.scene = null;
    render(<Scene />);
    expect(screen.getByText("nothing seen yet")).toBeInTheDocument();
  });
});

