/* Motion v3, from docs/design/STYLE-V3.md section 7 and docs/design/keyframes.css. */

/* KEYFRAMES_BLOCK (SNIPPETS B), unchanged. */
@keyframes riseIn{from{opacity:0;transform:translateY(14px);filter:blur(6px)}to{opacity:1;transform:none;filter:blur(0)}}
@keyframes popIn{0%{opacity:0;transform:scale(.82)}60%{opacity:1;transform:scale(1.04)}100%{opacity:1;transform:scale(1)}}
@keyframes sheetUp{from{transform:translateY(100%)}to{transform:none}}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
@keyframes orbBreathe{0%,100%{transform:scale(1)}50%{transform:scale(1.045)}}
@keyframes orbSpin{to{transform:rotate(360deg)}}
@keyframes orbListen{0%,100%{transform:scale(1)}20%{transform:scale(1.10)}45%{transform:scale(.97)}70%{transform:scale(1.07)}}
@keyframes ripple{0%{transform:scale(1);opacity:.6}100%{transform:scale(1.9);opacity:0}}
@keyframes glowPulse{0%,100%{opacity:.5}50%{opacity:1}}
@keyframes bar{0%,100%{transform:scaleY(.3)}50%{transform:scaleY(1)}}
@keyframes dot{0%,80%,100%{opacity:.25;transform:translateY(0)}40%{opacity:1;transform:translateY(-3px)}}
@keyframes caret{0%,49%{opacity:1}50%,100%{opacity:0}}
@keyframes bracketLock{0%{opacity:0;transform:scale(1.12)}100%{opacity:1;transform:scale(1)}}
@keyframes scan{0%{transform:translateY(0);opacity:0}10%{opacity:1}90%{opacity:1}100%{transform:translateY(276px);opacity:0}}
@keyframes drawCheck{from{stroke-dashoffset:24}to{stroke-dashoffset:0}}
@keyframes strike{from{background-size:0% 2px}to{background-size:100% 2px}}
@keyframes underline{from{background-size:0% 2px}to{background-size:100% 2px}}
@keyframes shimmer{from{background-position:-200% 0}to{background-position:200% 0}}
@keyframes floaty{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}
@keyframes bump{0%,100%{transform:scale(1)}40%{transform:scale(1.18)}}
@keyframes flyToTab{0%{transform:none;opacity:1}100%{transform:translate(118px,330px) scale(.2);opacity:0}}

/* Named motions that apply to whole elements. */
@layer components {
  /* 1. Screen enter: children rise in, 50ms stagger top to bottom. */
  .screen-enter > * {
    animation: riseIn var(--dur-3) var(--ease-out) both;
  }
  .screen-enter > :nth-child(2) { animation-delay: calc(var(--stagger) * 1); }
  .screen-enter > :nth-child(3) { animation-delay: calc(var(--stagger) * 2); }
  .screen-enter > :nth-child(4) { animation-delay: calc(var(--stagger) * 3); }
  .screen-enter > :nth-child(5) { animation-delay: calc(var(--stagger) * 4); }
  .screen-enter > :nth-child(n + 6) { animation-delay: calc(var(--stagger) * 5); }

  .rise-in {
    animation: riseIn var(--dur-3) var(--ease-out) both;
  }

  /* 6. Sheet rise. */
  .sheet-up {
    animation: sheetUp var(--dur-4) var(--ease-sheet) both;
  }

  /* 5. Label pop, checks, kept badge. */
  .pop-in {
    animation: popIn var(--dur-2) var(--ease-pop) both;
  }

  .fade-in {
    animation: fadeIn var(--dur-2) var(--ease-out) both;
  }

  /* 2. Press: scale 0.97 in 120ms, release with pop. */
  .press {
    transition: transform var(--dur-2) var(--ease-pop), background-color var(--dur-2) var(--ease-out),
      color var(--dur-2) var(--ease-out);
  }
  .press:active {
    transform: scale(0.97);
    transition: transform var(--dur-1) var(--ease-out);
  }

  /* 11. Tab icon bump. */
  .bump {
    animation: bump var(--dur-3) var(--ease-pop);
  }

  /* 13. Skeleton shimmer on loading surfaces. */
  .shimmer {
    background: linear-gradient(90deg, var(--sunken) 0%, var(--card) 50%, var(--sunken) 100%);
    background-size: 200% 100%;
    animation: shimmer 1.6s linear infinite;
  }

  .caret {
    animation: caret 1s steps(1) infinite;
  }

  /* 6/7. Noé orb states. */
  .orb-glow {
    animation: glowPulse var(--dur-loop) var(--ease-loop) infinite;
  }
  .orb-core {
    transition: opacity var(--dur-2) var(--ease-out);
  }
  .orb-breathe .orb-core {
    animation: orbBreathe var(--dur-loop) var(--ease-loop) infinite;
  }
  .orb-breathe .orb-spin {
    animation: orbSpin 12s linear infinite;
  }
  .orb-listen .orb-core {
    animation: orbListen 1.1s var(--ease-loop) infinite;
  }
  .orb-listen .orb-glow {
    animation-duration: 1.1s;
    opacity: 1;
  }
  .orb-listen .orb-spin {
    animation: orbSpin 12s linear infinite;
  }
  .orb-think .orb-core {
    opacity: 0.75;
  }
  .orb-think .orb-spin {
    animation: orbSpin 2.2s linear infinite;
  }
  .orb-speak .orb-core {
    animation: orbBreathe 1.4s var(--ease-loop) infinite;
  }
  .orb-speak .orb-spin {
    animation: orbSpin 12s linear infinite;
  }
  .orb-ring {
    animation: ripple 1.6s var(--ease-out) infinite;
  }
  .orb-speak .orb-ring {
    animation-duration: 2s;
  }
  .orb-ring + .orb-ring {
    animation-delay: 0.8s;
  }
  .orb-dot {
    animation: dot 1.2s infinite;
  }
  .orb-dot:nth-child(2) { animation-delay: 0.15s; }
  .orb-dot:nth-child(3) { animation-delay: 0.3s; }
}

/* Reduce Motion: moves and scales become a 200ms crossfade, loops stop, orb rests at idle, rings hidden. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
    animation-delay: 0ms !important;
    scroll-behavior: auto !important;
  }

  .screen-enter > *,
  .rise-in,
  .sheet-up,
  .pop-in,
  .fade-in {
    animation: fadeIn 200ms linear both !important;
  }

