/* Glass is for controls and navigation only, never cards, lists or text.
   Components layer, so Tailwind utilities (position, size) still win. */
@layer components {
  .glass-light,
  .glass-dark,
  .glass-clear {
    position: relative;
    overflow: hidden;
  }

  .glass-light {
    background: var(--glass-light-bg);
    backdrop-filter: blur(var(--glass-blur)) saturate(170%);
    -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(170%);
    border: 1px solid var(--glass-light-border);
    box-shadow: var(--glass-light-shadow);
    color: var(--ink);
  }

  .glass-dark {
    background: var(--glass-dark-bg);
    backdrop-filter: blur(var(--glass-blur)) saturate(170%);
    -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(170%);
    border: 1px solid var(--glass-dark-border);
    box-shadow: var(--glass-dark-shadow);
    color: var(--night-text);
  }

  .glass-clear {
    background: var(--glass-clear-bg);
    backdrop-filter: blur(var(--glass-clear-blur)) saturate(150%);
    -webkit-backdrop-filter: blur(var(--glass-clear-blur)) saturate(150%);
    border: 1px solid var(--glass-clear-border);
    box-shadow: var(--glass-clear-shadow);
    color: var(--snow);
  }

  /* Top highlight, painted under the content of the element. */
  .glass-specular {
    isolation: isolate;
  }

  .glass-specular::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: var(--glass-specular);
    pointer-events: none;
  }

  .glass-dark.glass-specular::before {
    background: var(--glass-specular-dark);
  }

  .tint-moss {
    background: var(--glass-tint-moss);
    color: var(--moss);
  }

  .glass-dark .tint-moss {
    background: var(--glass-tint-moss-dark);
    color: var(--moss-on-dark);
  }

  /* Soft glows so the glass has something to refract. */
  .bg-paper {
    background: radial-gradient(70% 45% at 85% -5%, rgba(47, 163, 127, 0.1), rgba(47, 163, 127, 0) 70%), var(--paper);
  }

  .bg-night {
    background: var(--night);
  }
}

@media (prefers-reduced-transparency: reduce) {
  .glass-light {
    background: #FFFFFF;
    border-color: var(--line);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }

  .glass-dark {
    background: #1C1E22;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }

  .glass-clear {
    background: rgba(22, 24, 28, 0.78);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }
}
