import type { CSSProperties } from "react";

export type OrbSize = 28 | 44 | 96 | 168;
export type OrbState = "idle" | "listening" | "thinking" | "speaking";

// Orb gradient (STYLE-V3 section 2), only inside the orb and its glow.
export const ORB_GRADIENT = "conic-gradient(from 0deg, #0E5C47, #2FA37F, #BFE8D6, #F0C766, #2FA37F, #0E5C47)";

const motion: Record<OrbState, string> = {
  idle: "orb-breathe",
  listening: "orb-listen",
  thinking: "orb-think",
  speaking: "orb-speak",
};

const ring: Partial<Record<OrbState, string>> = {
  listening: "rgba(47,163,127,0.55)",
  speaking: "rgba(240,199,102,0.6)",
};

interface Props {
  size?: OrbSize;
  state?: OrbState;
  className?: string;
}

/** The Noé orb (SNIPPETS C): one element, four states, same construction at every size. */
export default function Orb({ size = 44, state = "idle", className = "" }: Props) {
  const rings = ring[state];
  const glow = state === "listening" ? 0.6 : 0.38;
  return (
    <div className={`inline-flex shrink-0 flex-col items-center gap-2 ${className}`}>
      <div
        role="img"
        aria-label={`Noé, ${state}`}
        data-state={state}
        className={`relative shrink-0 ${motion[state]}`}
        style={{ width: size, height: size }}
      >
        {rings && (
          <>
            <div className="orb-ring absolute inset-0 rounded-full" style={{ border: `2px solid ${rings}` }} />
            <div className="orb-ring absolute inset-0 rounded-full" style={{ border: `2px solid ${rings}` }} />
          </>
        )}
        <div
          className="orb-glow absolute rounded-full"
          style={{
            inset: "-18%",
            background: `radial-gradient(closest-side, rgba(47,163,127,${glow}), rgba(47,163,127,0))`,
            filter: "blur(10px)",
          }}
        />
        <div
          className="orb-core absolute inset-0 overflow-hidden rounded-full"
          style={{ boxShadow: "inset 0 0 0 1px rgba(255,255,255,0.35), 0 14px 36px rgba(14,92,71,0.28)" }}
        >
          <div className="orb-spin absolute" style={{ "--orb-gradient": ORB_GRADIENT, inset: "-35%", background: "var(--orb-gradient)", filter: "blur(14px)" } as CSSProperties} />
          <div
            className="absolute inset-0 rounded-full"
            style={{ background: "radial-gradient(55% 45% at 34% 26%, rgba(255,255,255,0.78), rgba(255,255,255,0) 62%)" }}
          />
        </div>
      </div>
      {state === "thinking" && (
        <div aria-hidden className="flex justify-center gap-1.5">
          <span className="orb-dot h-1.5 w-1.5 rounded-full bg-current" />
          <span className="orb-dot h-1.5 w-1.5 rounded-full bg-current" />
          <span className="orb-dot h-1.5 w-1.5 rounded-full bg-current" />
        </div>
      )}
    </div>
  );
}
import type { ButtonHTMLAttributes, ReactNode } from "react";

interface Props extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "aria-label"> {
  "aria-label": string;
  variant?: "light" | "dark";
  children: ReactNode;
}

/** 44px floating circle for back, close and settings at the top corners (SNIPPETS D). */
export default function GlassButton({ variant = "light", className = "", children, type = "button", ...rest }: Props) {
  return (
    <button
      type={type}
      {...rest}
      className={`glass-${variant} glass-specular press flex h-11 w-11 shrink-0 cursor-pointer items-center justify-center rounded-[22px] p-0 ${className}`}
    >
      {children}
    </button>
  );
}

export type MicState = "idle" | "listening" | "speaking" | "thinking";

/**
 * The 88px mic control face. Clear glass over night and camera, light glass on paper.
 * The caller owns the element, its handlers and its label.
 */
export function MicFace({ state, surface = "dark" }: { state: MicState; surface?: "light" | "dark" }) {
  const dot =
    state === "listening"
      ? "bg-moss"
      : state === "speaking"
        ? "bg-sun"
        : surface === "dark"
          ? state === "thinking"
            ? "bg-snow/30"
            : "bg-snow/60"
          : state === "thinking"
            ? "bg-ink/30"
            : "bg-ink/50";
  return (
    <span aria-hidden className="relative flex h-[104px] w-[104px] items-center justify-center">
      {state === "listening" && (
        <span className="absolute inset-0 rounded-[var(--radius-pill)] border border-moss opacity-20 motion-safe:animate-ping" />
      )}
      <span
        className={`${surface === "dark" ? "glass-clear" : "glass-light"} glass-specular flex h-[88px] w-[88px] items-center justify-center rounded-[var(--radius-pill)] border-2 ${
          surface === "dark" ? "border-snow/60" : "border-snow/90"
        }`}
      >
        {state === "listening" && <span className="absolute h-16 w-16 rounded-[var(--radius-pill)] border border-moss" />}
        <span className={`relative h-6 w-6 rounded-[var(--radius-pill)] ${dot}`} />
      </span>
    </span>
  );
}

